<?php
function seo_escape($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function seo_slug(array $p):string{if(!empty($p['slug']))return $p['slug'];$hash=2166136261;foreach(mb_str_split($p['title']) as $c){$units=unpack('n*',mb_convert_encoding($c,'UTF-16BE','UTF-8'));$hash^=$units[1];$hash=($hash*16777619)&0xffffffff;}return 'project-'.dechex($hash);}
function seo_data(array $defaults):array{
 $rows=many("SELECT id,data FROM content WHERE id='public' OR id LIKE 'service:%' OR id LIKE 'faq:%' OR id LIKE 'seo:%'");$public=['projects'=>[],'contacts'=>[]];$services=[];$faq=[];$overrides=[];
 foreach($defaults['services'] as $s)$services[$s['slug']]=$s;foreach($defaults['faq'] as $f)$faq[$f['id']]=$f;
 foreach($rows as $r){$v=json_decode($r['data'],true);if($r['id']==='public')$public=$v;elseif(str_starts_with($r['id'],'service:'))$services[$v['slug']]=array_merge($services[$v['slug']]??[],$v);elseif(str_starts_with($r['id'],'faq:'))$faq[$v['id']]=array_merge($faq[$v['id']]??[],$v);elseif(str_starts_with($r['id'],'seo:'))$overrides[substr($r['id'],4)]=$v;}
 return ['contacts'=>$public['contacts']??[],'projects'=>array_merge(array_values(array_filter($public['projects']??[],fn($p)=>($p['confirmed']??false)===true)),$defaults['projects']),'services'=>array_values(array_filter($services,fn($s)=>$s['status']!=='Скрыта')),'faq'=>array_values(array_filter($faq,fn($f)=>$f['published'])),'overrides'=>$overrides];
}
function seo_blocks(array $blocks):string{$out='';foreach($blocks as [$h,$p])$out.='<section><h2>'.seo_escape($h).'</h2><p>'.seo_escape($p).'</p></section>';return $out;}
function seo_page(string $path,array $data):array{
 $title='';$description='';$body='';$status=200;$index=true;
 if($path==='/'){$title='OVERTAKE — цифровое агентство в Пскове';$description='Разработка сайтов, Telegram-ботов, CRM, приложений и автоматизация бизнеса. От обсуждения идеи до запуска и поддержки.';$body=seo_blocks([['Цифровые решения для бизнеса',$description],['Официальное сотрудничество','ИП Игнатенко Илья Анатольевич. ИНН 511007182150. ОГРНИП 325600000016430. Стоимость и сроки согласуются в договоре.']]);}
 elseif($path==='/services'){$title='Продукты и решения — OVERTAKE';$description='Сайты, боты, приложения, ИИ, дизайн, продвижение и сопровождение. Каталог решений с ценами, готовыми пакетами и калькулятором.';foreach($data['services'] as $s)$body.='<section><h2><a href="/services?product='.seo_escape($s['slug']).'">'.seo_escape($s['name']).'</a></h2><p>'.seo_escape($s['description']).'</p><p>'.seo_escape($s['status']).'</p></section>';}
 elseif(str_starts_with($path,'/services/')){foreach($data['services'] as $item)if('/services/'.$item['slug']===$path)return ['status'=>301,'redirect'=>'/services?product='.rawurlencode($item['slug']),'index'=>false];$status=404;}
 elseif($path==='/about'){$title='О компании — цифровое агентство OVERTAKE';$description='Разработка и дизайн из Пскова. Два основателя ведут проекты от первой встречи до запуска и поддержки.';$body=seo_blocks([['Как мы работаем','Согласовываем бриф, объём, бюджет и сроки в договоре. Проектируем, показываем результат по этапам, тестируем и передаём доступы.']]);}
 elseif($path==='/contacts'){$title='Контакты агентства OVERTAKE';$description='Связаться с OVERTAKE по телефону +7 (951) 750-67-00, обсудить проект онлайн или согласовать личную встречу в Пскове.';$blocks=[['Телефон','+7 (951) 750-67-00']];foreach(['address'=>'Адрес офиса','email'=>'Email','telegram'=>'Telegram','telegram2'=>'Telegram','hours'=>'Часы приёма'] as $key=>$label)if(!empty($data['contacts'][$key]))$blocks[]=[$label,$data['contacts'][$key]];$blocks[]=['Исполнитель','ИП Игнатенко Илья Анатольевич. ИНН 511007182150. ОГРНИП 325600000016430.'];$body=seo_blocks($blocks);}
 elseif($path==='/faq'){$title='Вопросы и ответы — OVERTAKE';$description='Ответы на вопросы о стоимости, сроках, договорах, правках, поддержке и передаче исходного кода.';$body=seo_blocks(array_map(fn($f)=>[$f['question'],$f['answer']],$data['faq']));}
 elseif($path==='/portfolio'){$title='Портфолио — OVERTAKE';$description='Реальные клиентские проекты OVERTAKE. Состав решений, задачи и технологии.';foreach($data['projects'] as $p)$body.='<section><h2><a href="/portfolio/'.seo_escape(seo_slug($p)).'">'.seo_escape($p['title']).'</a></h2><p>'.seo_escape($p['description']).'</p><p>'.(!empty($p['concept'])?'Дизайн-концепция':'Клиентский проект').'</p></section>';}
 elseif(str_starts_with($path,'/portfolio/')){$p=null;foreach($data['projects'] as $item)if('/portfolio/'.seo_slug($item)===$path)$p=$item;if($p){$title=$p['title'].' — OVERTAKE';$description=$p['description'];$blocks=[[!empty($p['concept'])?'Дизайн-концепция':'Клиентский проект',$p['description']]];foreach(['task'=>'Задача','result'=>'Результат','technologies'=>'Технологии'] as $key=>$label)if(!empty($p[$key]))$blocks[]=[$label,$p[$key]];$body=seo_blocks($blocks);}else $status=404;}
 elseif(preg_match('~^/cabinet(?:/[a-z-]+)?$~D',$path)){$index=false;$title='Рабочая система — OVERTAKE';$description='Рабочая система агентства и кабинет заказчика.';$body='<p>Для просмотра данных войдите в свой аккаунт.</p>';}
 else{$labels=['/brief'=>'Бриф проекта','/calculator'=>'Параметры проекта','/account'=>'Личный кабинет','/admin'=>'Кабинет команды','/legal'=>'Реквизиты и документы','/privacy'=>'Политика обработки персональных данных','/personal-data-consent'=>'Согласие на обработку данных','/cookies'=>'Политика cookie','/terms'=>'Пользовательское соглашение','/offer'=>'Условия заказа услуг','/service-agreement'=>'Договор оказания услуг','/marketing-consent'=>'Рекламные рассылки'];if(isset($labels[$path])){$index=false;$title=$labels[$path].' — OVERTAKE';$description='OVERTAKE — информация и взаимодействие по проектам.';$body='<p>Раздел доступен в интерактивном интерфейсе сайта.</p>';}else $status=404;}
 if($status===404){$title='Страница не найдена — OVERTAKE';$description='Проверьте адрес или откройте каталог услуг OVERTAKE.';$body='<p>Эта страница не существует или больше не опубликована.</p><a href="/services">Открыть услуги</a>';$index=false;}
 if($index&&$status===200&&isset($data['overrides'][$path])){$title=$data['overrides'][$path]['title']?:$title;$description=$data['overrides'][$path]['description']?:$description;}
 return compact('title','description','body','status','index');
}
function render_seo(string $path):never{
 if($path==='/pricing'){header('Location: /services?view=pricing',true,301);exit;}
 global $config,$release;$defaults=json_decode(file_get_contents($release.'/client/assets/seo-data.js'),true,512,JSON_THROW_ON_ERROR);$data=seo_data($defaults);$origin=rtrim($config['origin'],'/');$production=$origin==='https://helmerzy.tw1.ru';header('Cache-Control: no-cache');if(!$production)header('X-Robots-Tag: noindex, nofollow');
 if($path==='/robots.txt'){header('Content-Type: text/plain; charset=utf-8');if($_SERVER['REQUEST_METHOD']!=='HEAD')echo $production?"User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /admin\nDisallow: /account\nDisallow: /cabinet\nDisallow: /brief\nDisallow: /calculator\nSitemap: $origin/sitemap.xml\n":"User-agent: *\nDisallow: /\n";exit;}
 if($path==='/sitemap.xml'){header('Content-Type: application/xml; charset=utf-8');if($_SERVER['REQUEST_METHOD']!=='HEAD'){$paths=['/','/services','/about','/contacts','/faq','/portfolio'];foreach($data['projects'] as $p)$paths[]='/portfolio/'.seo_slug($p);echo '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach($paths as $url)echo '<url><loc>'.seo_escape($origin.$url).'</loc></url>';echo '</urlset>';}exit;}
 $page=seo_page($path,$data);if(isset($page['redirect'])){header('Location: '.$page['redirect'],true,301);exit;}http_response_code($page['status']);header('Content-Type: text/html; charset=utf-8');$canonical=$origin.$path;$robots=$production&&$page['index']?'index,follow':'noindex,nofollow';$head='<title>'.seo_escape($page['title']).'</title><meta name="description" content="'.seo_escape($page['description']).'"><meta name="robots" content="'.$robots.'"><link rel="canonical" href="'.seo_escape($canonical).'"><link rel="icon" type="image/svg+xml" href="/assets/overtake-mark-v1.svg">';foreach(['title'=>$page['title'],'description'=>$page['description'],'url'=>$canonical,'type'=>'website','locale'=>'ru_RU','site_name'=>'OVERTAKE'] as $key=>$value)$head.='<meta property="og:'.$key.'" content="'.seo_escape($value).'">';
 if($page['status']===200)$head.='<script type="application/ld+json">'.json_encode(['@context'=>'https://schema.org','@type'=>'WebPage','name'=>$page['title'],'description'=>$page['description'],'url'=>$canonical,'isPartOf'=>['@type'=>'WebSite','name'=>'OVERTAKE','url'=>$origin]],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';
 $html=file_get_contents($release.'/client/index.html');$html=preg_replace('~<title>.*?</title>~s','',$html);$html=preg_replace('~<meta\s+name="description"[^>]*>~i','',$html);$html=str_replace('</head>',$head.'</head>',$html);$nav='<a href="/">OVERTAKE</a> · <a href="/services">Продукты и решения</a> · <a href="/portfolio">Портфолио</a> · <a href="/about">О компании</a> · <a href="/contacts">Контакты</a> · <a href="/faq">FAQ</a>';$html=str_replace('<div id="root"></div>','<div id="root"><main class="seo-fallback"><nav>'.$nav.'</nav><h1>'.seo_escape($page['title']).'</h1><p>'.seo_escape($page['description']).'</p>'.$page['body'].'</main></div>',$html);if($_SERVER['REQUEST_METHOD']!=='HEAD')echo $html;exit;
}
